        [MenuItem("BubuTown/Create StarBay Interior Decoration Prototype")]
        public static void CreateStarBayInteriorDecorationPrototype()
        {
            EnsureMaterials();
            var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
            scene.name = "StarBayInteriorDecorationPrototype";

            var root = new GameObject("星湾镇_室内与装修原型");
            CreateLighting(root.transform);
            CreateHotelRoom(root.transform);
            var suiteRefs = CreateStarterSuite(root.transform);
            CreateFurnitureStyleGallery(root.transform);
            CreateDecoratedThemePreview(root.transform);
            CreateBlenderFurnitureShowcase(root.transform);
            CreatePinkPolishedRoom(root.transform);
            CreateTargetDirectionApartment(root.transform);
            CreatePlayerAndRuntime(root.transform, suiteRefs);
            CreateCamera(root.transform);
            CreateReport();

            Directory.CreateDirectory(Path.GetDirectoryName(ScenePath));
            EditorSceneManager.SaveScene(scene, ScenePath);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            Debug.Log("[StarBay] Interior decoration prototype created: " + ScenePath);
        }

        [MenuItem("BubuTown/Build StarBay Chinese Interior Furniture Prefabs")]
        public static void BuildStarBayChineseInteriorFurniturePrefabs()
        {
            Directory.CreateDirectory(KenneyPrefabFolder);
            foreach (var spec in KenneyPrefabSpecs())
            {
                var root = new GameObject(spec.ChineseName);
                KenneyModelFit(root.transform, spec.ChineseName + "_模型", spec.ModelName, Vector3.zero, spec.Rotation, spec.TargetSize);
                PrefabUtility.SaveAsPrefabAsset(root, KenneyPrefabFolder + "/" + spec.ChineseName + ".prefab");
                Object.DestroyImmediate(root);
            }

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            Debug.Log("[StarBay] Chinese Kenney interior furniture prefabs built: " + KenneyPrefabFolder);
        }

