        [MenuItem("BubuTown/Capture StarBay Interior Decoration Prototype Preview")]
        public static void CaptureStarBayInteriorDecorationPrototypePreview()
        {
            if (!File.Exists(ScenePath))
            {
                CreateStarBayInteriorDecorationPrototype();
            }

            EditorSceneManager.OpenScene(ScenePath, OpenSceneMode.Single);
            var cameraObject = GameObject.Find("星湾镇_室内与装修原型/05_室内相机/室内第三人称相机");
            if (cameraObject == null)
            {
                throw new System.Exception("[StarBay] Missing interior preview camera.");
            }

            var image = new Texture2D(1600, 1000, TextureFormat.RGB24, false);
            Fill(image, new Color(0.68f, 0.76f, 0.84f));
