        private static void CreateLighting(Transform root)
        {
            var group = Group(root, "00_室内光照");
            RenderSettings.ambientMode = UnityEngine.Rendering.AmbientMode.Flat;
            RenderSettings.ambientLight = new Color(0.68f, 0.65f, 0.59f);

            var sunObject = new GameObject("柔和窗外日光");
            sunObject.transform.SetParent(group, false);
            sunObject.transform.rotation = Quaternion.Euler(48f, -35f, 0f);
            var sun = sunObject.AddComponent<Light>();
            sun.type = LightType.Directional;
            sun.intensity = 0.56f;
            sun.color = new Color(1f, 0.91f, 0.76f);
            sun.shadows = LightShadows.Soft;
            sun.shadowStrength = 0.24f;
        }

