            DisableRendererShadows(sheer);
            Cube(group, "旅店_v134_窗框玻璃高光", new Vector3(-4.05f, 1.77f, 2.090f), new Vector3(0.020f, 0.58f, 0.006f), "GlassHighlightSoft").transform.localRotation = Quaternion.Euler(0f, 0f, -16f);

            Cube(group, "旅店_v134_床面温白被芯", new Vector3(-7.02f, 0.650f, 0.30f), new Vector3(1.02f, 0.050f, 1.36f), "HotelBedding");
