            group.localPosition = position;
            Cube(group, "展示_地台", Vector3.zero, new Vector3(3.2f, 0.10f, 2.5f), floorMaterial);
            Cube(group, "展示_后墙材质板", new Vector3(0f, 1.15f, 1.28f), new Vector3(3.2f, 2.3f, 0.08f), backMaterial);
            GeneratedBlenderModelFit(group, assetName + "_Blender生成模型", assetName, new Vector3(0f, 0.08f, -0.15f), rotation, targetSize);
            Label(group, "标注_展示家具名", assetName, new Vector3(0f, 2.48f, -0.82f), 0.035f);
        }

