        private static void AddCardboardFaceSet(Transform parent, string prefix, Vector3 position, float height, float width, bool withSticker)
        {
            Cube(parent, prefix + "_整面细纸纹覆盖", position, new Vector3(0.006f, height, width), "TargetCardboardFiberWarm");
            Cube(parent, prefix + "_封箱胶带横向", position + new Vector3(-0.009f, height * 0.18f, 0f), new Vector3(0.004f, 0.030f, width * 0.86f), "CardboardTapeSoft");
            if (!withSticker)
            {
                Cube(parent, prefix + "_手写短线", position + new Vector3(-0.012f, -height * 0.05f, 0f), new Vector3(0.004f, 0.020f, width * 0.48f), "CardboardInkSoft");
                return;
            }

            var sticker = Cube(parent, prefix + "_奶油色软边标签纸", position + new Vector3(-0.012f, -height * 0.06f, 0f), new Vector3(0.004f, height * 0.42f, width * 0.55f), "CardboardLabelPaperSoft");
            DisableRendererShadows(sticker);
            Cube(parent, prefix + "_标签上短字线", position + new Vector3(-0.016f, height * 0.02f, 0f), new Vector3(0.003f, 0.014f, width * 0.32f), "CardboardInkSoft");
            Cube(parent, prefix + "_标签下短字线", position + new Vector3(-0.016f, -height * 0.08f, 0f), new Vector3(0.003f, 0.014f, width * 0.25f), "CardboardInkSoft");
            Cube(parent, prefix + "_小搬家箭头", position + new Vector3(-0.017f, -height * 0.16f, -width * 0.02f), new Vector3(0.003f, 0.040f, 0.012f), "CardboardInkSoft");
            Cube(parent, prefix + "_小搬家箭头横", position + new Vector3(-0.017f, -height * 0.17f, width * 0.035f), new Vector3(0.003f, 0.012f, 0.070f), "CardboardInkSoft");
        }

