            leaf.transform.localRotation = Quaternion.Euler(euler);
            Sphere(parent, name + "_浅色中脉", position + new Vector3(0f, 0.006f, 0f), new Vector3(scale.x * 0.16f, scale.y * 0.20f, scale.z * 0.72f), "PlantLeafHighlight").transform.localRotation = Quaternion.Euler(euler);
        }

