        private static void AddSoftSlipper(Transform parent, string name, Vector3 position, float yaw)
        {
            var holder = Group(parent, name);
            holder.localPosition = position;
            holder.localRotation = Quaternion.Euler(0f, yaw, 0f);
            Sphere(holder, name + "_圆头软鞋底", new Vector3(0f, 0.010f, 0f), new Vector3(0.125f, 0.022f, 0.074f), "BlushPink");
            Sphere(holder, name + "_后跟浅压面", new Vector3(0f, 0.016f, 0.050f), new Vector3(0.095f, 0.012f, 0.036f), "BeddingHighlightWarm");
            Cube(holder, name + "_奶油布面鞋带", new Vector3(0f, 0.046f, -0.018f), new Vector3(0.095f, 0.012f, 0.030f), "SoftCream").transform.localRotation = Quaternion.Euler(0f, 0f, 8f);
            Sphere(holder, name + "_贴地软影", new Vector3(0f, -0.006f, 0.006f), new Vector3(0.135f, 0.003f, 0.082f), "SoftShadow");
        }

