        private static void AddStableMovingBox(Transform parent, string name, Vector3 position, Vector3 size, bool labeled)
        {
            var box = Group(parent, name);
            Cube(box, "箱体_暖纸板纹理", position, size, "TargetCardboardFiberWarm");
            Cube(box, "正面_封箱胶带", position + new Vector3(-size.x * 0.51f, size.y * 0.08f, 0f), new Vector3(0.006f, size.y * 0.10f, size.z * 0.78f), "CardboardTapeSoft");
            Cube(box, "正面_中线折痕", position + new Vector3(-size.x * 0.515f, 0f, 0f), new Vector3(0.005f, size.y * 0.72f, 0.010f), "StickerShadowSoft");
            Cube(box, "顶面_低调胶带", position + new Vector3(0f, size.y * 0.51f, 0f), new Vector3(size.x * 0.72f, 0.006f, size.z * 0.070f), "CardboardTapeSoft");
            if (labeled)
            {
                Cube(box, "正面_软边搬家标签", position + new Vector3(-size.x * 0.525f, -size.y * 0.11f, 0f), new Vector3(0.004f, size.y * 0.33f, size.z * 0.42f), "CardboardLabelPaperSoft");
                Cube(box, "标签_手写短线一", position + new Vector3(-size.x * 0.535f, -size.y * 0.06f, 0f), new Vector3(0.003f, 0.012f, size.z * 0.24f), "CardboardInkSoft");
                Cube(box, "标签_手写短线二", position + new Vector3(-size.x * 0.535f, -size.y * 0.15f, 0f), new Vector3(0.003f, 0.012f, size.z * 0.18f), "CardboardInkSoft");
            }

            var shadow = Sphere(box, "底部_落地柔影", new Vector3(position.x, 0.128f, position.z), new Vector3(size.x * 0.55f, 0.006f, size.z * 0.52f), "SoftShadow");
            DisableRendererShadows(shadow);
        }

