        private static void SoftLeafPlant(Transform parent, string name, Vector3 localPosition, float scale, bool leaning)
        {
            var group = Group(parent, name);
            group.localPosition = localPosition;
            Sphere(group, "圆润陶土盆", new Vector3(0f, 0.05f * scale, 0f), new Vector3(0.18f * scale, 0.12f * scale, 0.18f * scale), "PlantPot");
            Sphere(group, "深色盆土", new Vector3(0f, 0.125f * scale, 0f), new Vector3(0.15f * scale, 0.020f * scale, 0.15f * scale), "PlantSoil");
            var offsets = leaning
                ? new[] { -0.28f, -0.14f, 0.04f, 0.20f, 0.34f }
                : new[] { -0.22f, -0.08f, 0.08f, 0.22f };
            for (var i = 0; i < offsets.Length; i++)
            {
                var x = offsets[i];
                var z = (i % 2 == 0 ? -0.04f : 0.05f) * scale;
                var y = (0.28f + 0.06f * (i % 3)) * scale;
                var leaf = Sphere(group, "椭圆叶片_" + i, new Vector3(x * scale, y, z), new Vector3(0.095f * scale, 0.030f * scale, 0.18f * scale), "PlantLeaf");
                leaf.transform.localRotation = Quaternion.Euler(leaning ? 0f : 8f, 22f + i * 24f, -18f + i * 9f);
                Cube(group, "细叶柄_" + i, new Vector3(x * 0.45f * scale, (0.22f + 0.025f * i) * scale, z * 0.55f), new Vector3(0.015f * scale, 0.18f * scale, 0.012f * scale), "PlantStem");
            }
        }

        private static void MoundedWindowPlanter(Transform parent, string name, Vector3 localPosition, float scale)
        {
            var group = Group(parent, name);
            group.localPosition = localPosition;
            Cube(group, "低矮长方木盆", new Vector3(0f, -0.035f * scale, 0f), new Vector3(0.54f * scale, 0.10f * scale, 0.13f * scale), "TargetWood");
            Cube(group, "深色土面", new Vector3(0f, 0.030f * scale, -0.004f * scale), new Vector3(0.48f * scale, 0.020f * scale, 0.10f * scale), "PlantSoil");
            for (var i = 0; i < 5; i++)
            {
                var x = (-0.21f + i * 0.105f) * scale;
                var y = (0.078f + 0.012f * (i % 2)) * scale;
                var z = (-0.010f + 0.018f * (i % 3 - 1)) * scale;
                var leaf = Sphere(group, "厚圆叶冠_" + i, new Vector3(x, y, z), new Vector3(0.085f * scale, 0.040f * scale, 0.060f * scale), "PlantLeaf");
                leaf.transform.localRotation = Quaternion.Euler(0f, i * 19f, 0f);
            }
            Cube(group, "木盆前沿高光", new Vector3(0f, 0.018f * scale, -0.070f * scale), new Vector3(0.46f * scale, 0.010f * scale, 0.010f * scale), "WoodVarnishHighlight");
        }

