        private static void DisableDescendantsByNameContains(Transform parent, params string[] nameParts)
        {
            var children = parent.GetComponentsInChildren<Transform>(true);
            foreach (var child in children)
            {
                foreach (var namePart in nameParts)
                {
                    if (child.name.Contains(namePart))
                    {
                        child.gameObject.SetActive(false);
                        break;
                    }
                }
            }
        }

        private static void AddFlatFrame(Transform parent, string name, Vector3 center, Vector2 size, string materialName)
        {
            var group = Group(parent, name);
            group.localPosition = center;
            Cube(group, "上边框", new Vector3(0f, size.y * 0.5f, 0f), new Vector3(size.x, 0.035f, 0.035f), materialName);
            Cube(group, "下边框", new Vector3(0f, -size.y * 0.5f, 0f), new Vector3(size.x, 0.035f, 0.035f), materialName);
            Cube(group, "左边框", new Vector3(-size.x * 0.5f, 0f, 0f), new Vector3(0.035f, size.y, 0.035f), materialName);
            Cube(group, "右边框", new Vector3(size.x * 0.5f, 0f, 0f), new Vector3(0.035f, size.y, 0.035f), materialName);
        }

        private static void AddSideWallFrame(Transform parent, string name, Vector3 center, Vector2 size, string materialName)
        {
            var group = Group(parent, name);
            group.localPosition = center;
            Cube(group, "上边框", new Vector3(0f, size.y * 0.5f, 0f), new Vector3(0.035f, 0.035f, size.x), materialName);
            Cube(group, "下边框", new Vector3(0f, -size.y * 0.5f, 0f), new Vector3(0.035f, 0.035f, size.x), materialName);
            Cube(group, "左边框", new Vector3(0f, 0f, -size.x * 0.5f), new Vector3(0.035f, size.y, 0.035f), materialName);
            Cube(group, "右边框", new Vector3(0f, 0f, size.x * 0.5f), new Vector3(0.035f, size.y, 0.035f), materialName);
        }

        private static void TargetApartmentBed(Transform parent, string name, Vector3 localPosition)
        {
            var group = Group(parent, name);
            group.localPosition = localPosition;
            var polishedBed = GeneratedBlenderModelFit(group, "目标公寓_目标图精修粉木单人床_Blender生成", "目标图精修粉木单人床", new Vector3(0f, 0f, 0f), Quaternion.identity, new Vector3(1.40f, 0.72f, 1.86f));
            if (polishedBed != null)
            {
