        private static void CreateStaticDecorationGrid(Transform parent, Vector2Int gridSize, float cellSize)
        {
            var columns = Mathf.Max(1, gridSize.x);
            var rows = Mathf.Max(1, gridSize.y);
            var width = columns * cellSize;
            var depth = rows * cellSize;
            for (var x = 0; x <= columns; x++)
            {
                Cube(parent, "可见装修网格_纵线_" + x, new Vector3(-width * 0.5f + x * cellSize, 0.035f, 0f), new Vector3(0.018f, 0.018f, depth), "GridLine");
            }
            for (var z = 0; z <= rows; z++)
            {
                Cube(parent, "可见装修网格_横线_" + z, new Vector3(0f, 0.04f, -depth * 0.5f + z * cellSize), new Vector3(width, 0.018f, 0.018f), "GridLine");
            }
        }

        private static void AddFloorPlanks(Transform parent, string prefix, float centerX, float y, float centerZ, float width, float depth, string materialName)
        {
            for (var i = 0; i <= 8; i++)
            {
                var z = centerZ - depth * 0.5f + i * depth / 8f;
                Cube(parent, prefix + "横向_" + i, new Vector3(centerX, y, z), new Vector3(width, 0.014f, 0.018f), materialName);
            }

            for (var i = 0; i <= 5; i++)
            {
                var x = centerX - width * 0.5f + i * width / 5f;
                Cube(parent, prefix + "纵向_" + i, new Vector3(x, y + 0.002f, centerZ), new Vector3(0.016f, 0.014f, depth), materialName);
            }
        }

        private static void AddBaseboards(Transform parent, string prefix, Vector3 longWallPosition, Vector3 longWallScale, Vector3 sideWallPosition, Vector3 sideWallScale)
        {
            Cube(parent, prefix + "北侧", longWallPosition, longWallScale, "WoodTrim");
            Cube(parent, prefix + "南侧", new Vector3(longWallPosition.x, longWallPosition.y, -longWallPosition.z), longWallScale, "WoodTrim");
            Cube(parent, prefix + "西侧", sideWallPosition, sideWallScale, "WoodTrim");
            Cube(parent, prefix + "东侧", new Vector3(-sideWallPosition.x + longWallPosition.x * 2f, sideWallPosition.y, sideWallPosition.z), sideWallScale, "WoodTrim");
        }

        private static void CurtainPleats(Transform parent, string prefix, Vector3 center, float width, float height, string materialName)
        {
            const int pleatCount = 5;
            for (var i = 0; i < pleatCount; i++)
            {
                var t = pleatCount == 1 ? 0.5f : i / (pleatCount - 1f);
                var x = center.x - width * 0.5f + width * t;
                var depthOffset = Mathf.Sin(t * Mathf.PI * 2f) * 0.025f;
                Cube(parent, prefix + "_" + (i + 1), new Vector3(x, center.y, center.z + depthOffset), new Vector3(0.055f, height, 0.08f), materialName);
            }
        }

        private static Texture2D RenderReviewView(string name, Vector3 position, Vector3 target, float fieldOfView)
        {
            var cameraObject = new GameObject("临时截图相机_" + name);
            cameraObject.transform.position = position;
            cameraObject.transform.rotation = Quaternion.LookRotation(target - position, Vector3.up);
            var camera = cameraObject.AddComponent<Camera>();
            camera.fieldOfView = fieldOfView;
            camera.nearClipPlane = 0.03f;
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = new Color(0.68f, 0.76f, 0.84f);

            var renderTexture = new RenderTexture(800, 500, 24);
            renderTexture.antiAliasing = 4;
            camera.targetTexture = renderTexture;
            camera.Render();

            RenderTexture.active = renderTexture;
            var image = new Texture2D(800, 500, TextureFormat.RGB24, false);
            image.ReadPixels(new Rect(0, 0, 800, 500), 0, 0);
            image.Apply();

            RenderTexture.active = null;
            camera.targetTexture = null;
            Object.DestroyImmediate(renderTexture);
            Object.DestroyImmediate(cameraObject);
            return image;
        }

        private static Texture2D RenderReviewViewWithHiddenRenderers(string name, Vector3 position, Vector3 target, float fieldOfView, params string[] hiddenNameFragments)
        {
            var disabledRenderers = new List<Renderer>();
            foreach (var renderer in Object.FindObjectsOfType<Renderer>())
            {
                if (!renderer.enabled)
                {
                    continue;
                }

                for (var i = 0; i < hiddenNameFragments.Length; i++)
                {
                    if (TransformNameChainContains(renderer.transform, hiddenNameFragments[i]))
                    {
                        renderer.enabled = false;
                        disabledRenderers.Add(renderer);
                        break;
                    }
                }
            }

            var image = RenderReviewView(name, position, target, fieldOfView);
            for (var i = 0; i < disabledRenderers.Count; i++)
            {
                if (disabledRenderers[i] != null)
                {
                    disabledRenderers[i].enabled = true;
                }
            }

            return image;
        }

        private static bool TransformNameChainContains(Transform transform, string fragment)
        {
            for (var current = transform; current != null; current = current.parent)
            {
                if (current.name.Contains(fragment))
                {
                    return true;
                }
            }

            return false;
        }

        private static Texture2D RenderTargetApartmentReviewView(string name, Vector3 position, Vector3 target, float fieldOfView, params string[] hiddenNameFragments)
        {
            var targetApartment = GameObject.Find("09_目标图方向三楼单身公寓");
            if (targetApartment == null)
            {
                return RenderReviewViewWithHiddenRenderers(name, position, target, fieldOfView, hiddenNameFragments);
            }

            var disabledRenderers = new List<Renderer>();
            var disabledLights = new List<Light>();
            foreach (var renderer in Object.FindObjectsOfType<Renderer>())
            {
                if (!renderer.enabled)
                {
                    continue;
                }

                var belongsToTargetApartment = renderer.transform == targetApartment.transform || renderer.transform.IsChildOf(targetApartment.transform);
                var shouldHide = !belongsToTargetApartment;
                if (!shouldHide)
                {
                    var objectName = renderer.gameObject.name;
                    for (var i = 0; i < hiddenNameFragments.Length; i++)
                    {
                        if (objectName.Contains(hiddenNameFragments[i]))
                        {
                            shouldHide = true;
                            break;
                        }
                    }
                }

                if (shouldHide)
                {
                    renderer.enabled = false;
                    disabledRenderers.Add(renderer);
                }
            }

            foreach (var light in Object.FindObjectsOfType<Light>())
            {
                if (!light.enabled)
                {
                    continue;
                }

                var belongsToTargetApartment = light.transform == targetApartment.transform || light.transform.IsChildOf(targetApartment.transform);
                var shouldHide = !belongsToTargetApartment;
                if (!shouldHide)
                {
                    for (var i = 0; i < hiddenNameFragments.Length; i++)
                    {
                        if (TransformNameChainContains(light.transform, hiddenNameFragments[i]))
                        {
                            shouldHide = true;
                            break;
                        }
                    }
                }

                if (shouldHide)
                {
                    light.enabled = false;
                    disabledLights.Add(light);
                }
            }

            var image = RenderReviewView(name, position, target, fieldOfView);
            for (var i = 0; i < disabledLights.Count; i++)
            {
                if (disabledLights[i] != null)
                {
                    disabledLights[i].enabled = true;
                }
            }

            for (var i = 0; i < disabledRenderers.Count; i++)
            {
                if (disabledRenderers[i] != null)
                {
                    disabledRenderers[i].enabled = true;
                }
            }

            return image;
        }

        private static void Blit(Texture2D destination, Texture2D source, int offsetX, int offsetY)
        {
            for (var y = 0; y < source.height; y++)
            {
                for (var x = 0; x < source.width; x++)
                {
                    destination.SetPixel(offsetX + x, offsetY + y, source.GetPixel(x, y));
                }
            }

            Object.DestroyImmediate(source);
        }

        private static void Fill(Texture2D texture, Color color)
        {
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    texture.SetPixel(x, y, color);
                }
            }
        }

        private static void DrawDivider(Texture2D texture, int position, bool vertical)
        {
            var dark = new Color(0.12f, 0.14f, 0.16f);
            for (var i = -4; i <= 4; i++)
            {
                if (vertical)
                {
                    var x = Mathf.Clamp(position + i, 0, texture.width - 1);
                    for (var y = 0; y < texture.height; y++)
                    {
                        texture.SetPixel(x, y, dark);
                    }
                }
                else
                {
                    var y = Mathf.Clamp(position + i, 0, texture.height - 1);
                    for (var x = 0; x < texture.width; x++)
                    {
                        texture.SetPixel(x, y, dark);
                    }
                }
            }
        }

