        private static void DrawRect(Texture2D texture, int x, int y, int width, int height, Color color)
        {
            var minX = Mathf.Clamp(x, 0, texture.width - 1);
            var maxX = Mathf.Clamp(x + width, 0, texture.width);
            var minY = Mathf.Clamp(y, 0, texture.height - 1);
            var maxY = Mathf.Clamp(y + height, 0, texture.height);
            for (var py = minY; py < maxY; py++)
            {
                for (var px = minX; px < maxX; px++)
                {
                    texture.SetPixel(px, py, color);
                }
            }
        }

        private static void DrawBorder(Texture2D texture, int x, int y, int width, int height, Color color)
        {
            DrawRect(texture, x, y, width, 2, color);
            DrawRect(texture, x, y + height - 2, width, 2, color);
            DrawRect(texture, x, y, 2, height, color);
            DrawRect(texture, x + width - 2, y, 2, height, color);
        }

        private static void DrawCircle(Texture2D texture, int centerX, int centerY, int radius, Color color)
        {
            var radiusSquared = radius * radius;
            for (var y = -radius; y <= radius; y++)
            {
                for (var x = -radius; x <= radius; x++)
                {
                    if (x * x + y * y > radiusSquared)
                    {
                        continue;
                    }

                    var px = centerX + x;
                    var py = centerY + y;
                    if (px >= 0 && px < texture.width && py >= 0 && py < texture.height)
                    {
                        texture.SetPixel(px, py, color);
                    }
                }
            }
        }

        private static void CreatePlayerAndRuntime(Transform root, SuiteRefs refs)
        {
            var group = Group(root, "04_主角与装修运行时");
            var player = new GameObject("大蘑菇_占位玩家");
            player.transform.SetParent(group, false);
            player.transform.position = new Vector3(2.25f, 0.15f, -0.9f);
            player.transform.rotation = Quaternion.Euler(0f, 18f, 0f);
            var controller = player.AddComponent<CharacterController>();
            controller.height = 1.45f;
            controller.radius = 0.26f;
            controller.center = new Vector3(0f, 0.72f, 0f);
            player.AddComponent<BubuTownPlayerController>().WalkSpeed = 2.8f;
            CreatePrototypeCharacter(player.transform);

            var canvas = CreateCanvas(group);
            var hudText = CreateHudText(canvas.transform);
            CreateDecorationCatalogPanel(canvas.transform);

            var runtime = new GameObject("装修模式_运行控制器");
            runtime.transform.SetParent(group, false);
            var decoration = runtime.AddComponent<BubuTownInteriorDecorationPrototype>();
            decoration.Player = player.transform;
            decoration.PlacementRoot = refs.PlacementRoot;
            decoration.PreviewRoot = refs.PreviewRoot;
            decoration.WallRenderers = refs.Walls;
            decoration.FloorRenderer = refs.Floor;
            decoration.RoomLights = refs.Lights;
            decoration.HudText = hudText;
            decoration.FinishSets = new[]
            {
                Finish("可爱粉色", "PinkWallpaper", "SoftFloor", new Color(1f, 0.78f, 0.86f), 1.25f),
                Finish("木质自然", "NaturalWallpaper", "WoodFloor", new Color(1f, 0.86f, 0.62f), 1.1f),
                Finish("现代简约", "ModernWallpaper", "ModernFloor", new Color(0.86f, 0.94f, 1f), 1.05f),
                Finish("蛋糕主题", "CakeWallpaper", "CreamFloor", new Color(1f, 0.82f, 0.58f), 1.22f),
                Finish("电竞主题", "EsportsWallpaper", "DarkFloor", new Color(0.38f, 0.78f, 1f), 1.35f)
            };
        }

