        private static void CreateCatalogMiniFurnitureIcon(Transform parent, CatalogStyle style, int index)
        {
            var icon = new GameObject("缩略图_v182_" + style.Name);
            icon.transform.SetParent(parent, false);
            var rect = icon.AddComponent<RectTransform>();
            rect.anchorMin = new Vector2(0f, 1f);
            rect.anchorMax = new Vector2(0f, 1f);
            rect.pivot = new Vector2(0f, 1f);
            rect.anchoredPosition = new Vector2(16f, -45f);
            rect.sizeDelta = new Vector2(96f, 38f);

            CreateCatalogIconPart(icon.transform, "缩略图_地面柔影", new Color(0.34f, 0.28f, 0.22f, 0.22f), new Vector2(8f, -30f), new Vector2(80f, 5f));
            if (index == 2)
            {
                CreateCatalogIconPart(icon.transform, "缩略图_现代沙发靠背", style.Furniture, new Vector2(10f, -5f), new Vector2(68f, 15f));
                CreateCatalogIconPart(icon.transform, "缩略图_现代沙发坐垫", Color.Lerp(style.Furniture, Color.white, 0.18f), new Vector2(6f, -18f), new Vector2(76f, 14f));
                CreateCatalogIconPart(icon.transform, "缩略图_现代茶几", style.Floor, new Vector2(18f, -31f), new Vector2(42f, 6f));
                CreateCatalogIconPart(icon.transform, "缩略图_落地灯", style.Light, new Vector2(84f, -7f), new Vector2(8f, 28f));
                return;
            }

            if (index == 4)
            {
                CreateCatalogIconPart(icon.transform, "缩略图_电竞桌面", style.Furniture, new Vector2(8f, -22f), new Vector2(72f, 8f));
                CreateCatalogIconPart(icon.transform, "缩略图_电竞显示器", style.Furniture, new Vector2(28f, -3f), new Vector2(38f, 18f));
                CreateCatalogIconPart(icon.transform, "缩略图_电竞屏幕光", style.Light, new Vector2(33f, -8f), new Vector2(28f, 9f));
                CreateCatalogIconPart(icon.transform, "缩略图_电竞键盘光", style.Light, new Vector2(26f, -31f), new Vector2(32f, 4f));
                CreateCatalogIconPart(icon.transform, "缩略图_霓虹灯柱", style.Light, new Vector2(84f, -8f), new Vector2(7f, 26f));
                return;
            }

            CreateCatalogIconPart(icon.transform, "缩略图_床头木架", style.Floor, new Vector2(5f, -5f), new Vector2(82f, 10f));
            CreateCatalogIconPart(icon.transform, "缩略图_床品主面", style.Furniture, new Vector2(9f, -15f), new Vector2(76f, 18f));
            CreateCatalogIconPart(icon.transform, "缩略图_枕头一", Color.Lerp(style.Wallpaper, Color.white, 0.28f), new Vector2(16f, -18f), new Vector2(24f, 8f));
            CreateCatalogIconPart(icon.transform, "缩略图_枕头二", Color.Lerp(style.Wallpaper, Color.white, 0.28f), new Vector2(53f, -18f), new Vector2(24f, 8f));
            CreateCatalogIconPart(icon.transform, "缩略图_床尾滚边", Color.Lerp(style.Furniture, Color.white, 0.22f), new Vector2(10f, -30f), new Vector2(74f, 5f));
            if (index == 3)
