        private static Texture2D GenerateCleanPlasterWall()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var n = Mathf.PerlinNoise(x * 0.035f, y * 0.035f);
                    var fine = Mathf.PerlinNoise(50f + x * 0.11f, 70f + y * 0.11f);
                    var value = 0.92f + n * 0.055f + fine * 0.018f;
                    texture.SetPixel(x, y, new Color(value, value, value * 0.985f));
                }
            }

            DrawRect(texture, 34, 118, 92, 22, new Color(0.18f, 0.52f, 0.64f));
            DrawRect(texture, 386, 124, 96, 22, new Color(0.92f, 0.70f, 0.42f));
            DrawRect(texture, 48, 142, 62, 5, new Color(1f, 0.88f, 0.58f));
            DrawRect(texture, 402, 148, 58, 5, new Color(1f, 0.92f, 0.68f));
            for (var i = 0; i < 5; i++)
            {
                DrawRect(texture, 46 + i * 13, 186, 8, 18, new Color(0.72f, 0.90f, 0.96f));
                DrawRect(texture, 46 + i * 13, 228, 8, 18, new Color(0.72f, 0.90f, 0.96f));
                DrawRect(texture, 392 + i * 14, 192, 9, 18, new Color(0.74f, 0.88f, 0.92f));
                DrawRect(texture, 392 + i * 14, 236, 9, 18, new Color(0.74f, 0.88f, 0.92f));
            }

            for (var row = 0; row < 4; row++)
            {
                DrawRect(texture, 38, 170 + row * 38, 94, 4, new Color(0.96f, 0.84f, 0.62f));
                DrawRect(texture, 382, 174 + row * 38, 100, 4, new Color(1f, 0.86f, 0.60f));
            }

            for (var step = 0; step < 18; step++)
            {
                var y = 78 + step * 5;
                var leftX = 220 - step * 5;
                var rightX = 292 + step * 5;
                DrawRect(texture, leftX, y, 2, 4, new Color(0.92f, 0.78f, 0.50f));
                DrawRect(texture, rightX, y, 2, 4, new Color(0.92f, 0.78f, 0.50f));
            }

            DrawRect(texture, 138, 254, 236, 5, new Color(0.96f, 0.94f, 0.78f));
            DrawRect(texture, 184, 245, 52, 4, new Color(0.98f, 0.96f, 0.84f));
            DrawRect(texture, 196, 239, 30, 3, new Color(0.38f, 0.48f, 0.52f));
            DrawCircle(texture, 344, 380, 18, new Color(1f, 0.92f, 0.68f, 0.62f));
            DrawCircle(texture, 344, 380, 8, new Color(1f, 0.86f, 0.48f, 0.78f));
            for (var i = 0; i < 7; i++)
            {
                DrawRect(texture, 292 + i * 13, 336 - i * 3, 34, 3, new Color(0.16f, 0.50f, 0.28f));
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GenerateCleanGridTile()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var tileX = x % 128;
                    var tileY = y % 128;
                    var grout = tileX < 4 || tileY < 4 || tileX > 123 || tileY > 123;
                    var n = Mathf.PerlinNoise(x * 0.025f, y * 0.025f);
                    var baseValue = 0.82f + n * 0.06f;
                    var color = grout
                        ? new Color(0.70f, 0.73f, 0.75f)
                        : new Color(baseValue, baseValue * 0.995f, baseValue * 0.96f);
                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GeneratePinkCurtainCheck()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var vertical = x % 64 < 9;
                    var horizontal = y % 64 < 9;
                    var pleat = 0.88f + Mathf.Sin(x * 0.08f) * 0.08f;
                    var color = new Color(1f, 0.70f, 0.82f) * pleat;
                    if (vertical || horizontal)
                    {
                        color = Color.Lerp(color, new Color(0.52f, 0.36f, 0.48f), 0.65f);
                    }

                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GeneratePinkHeartWallpaper()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var color = new Color(1f, 0.82f, 0.90f);
                    var cellX = x % 128 - 64;
                    var cellY = y % 128 - 64;
                    var heart = Mathf.Pow(cellX / 34f, 2f) + Mathf.Pow((cellY + 8f) / 28f, 2f) < 1f;
                    var notch = Mathf.Abs(cellX) < 9 && cellY > -22 && cellY < 5;
                    if (heart && !notch)
                    {
                        color = new Color(1f, 0.50f, 0.70f);
                    }

                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GenerateSoftPinkRoomWallpaper()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var paperNoise = Mathf.PerlinNoise(x * 0.018f, y * 0.018f) * 0.035f;
                    var color = new Color(1f, 0.87f + paperNoise, 0.92f + paperNoise);
                    var cellX = x % 96 - 48;
                    var cellY = y % 96 - 48;
                    var dot = cellX * cellX + cellY * cellY < 6 * 6;
                    var tinyHeart = Mathf.Pow(cellX / 13f, 2f) + Mathf.Pow((cellY + 3f) / 10f, 2f) < 1f;
                    var notch = Mathf.Abs(cellX) < 3 && cellY > -8 && cellY < 2;
                    if (dot)
                    {
                        color = new Color(1f, 0.70f, 0.82f);
                    }
                    else if (tinyHeart && !notch)
                    {
                        color = new Color(1f, 0.64f, 0.78f);
                    }

                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GenerateCakeSprinkleWallpaper()
        {
            var texture = NewGeneratedTexture();
            var sprinkleColors = new[]
            {
                new Color(1f, 0.42f, 0.54f),
                new Color(0.52f, 0.78f, 1f),
                new Color(1f, 0.78f, 0.28f),
                new Color(0.58f, 0.86f, 0.52f)
            };

            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var color = new Color(1f, 0.88f, 0.68f);
                    var hash = Mathf.Abs(Mathf.Sin((x * 12.9898f + y * 78.233f) * 0.02f) * 43758.5453f);
                    var sprinkle = hash - Mathf.Floor(hash) > 0.985f;
                    if (sprinkle)
                    {
                        var index = Mathf.Abs((x / 11 + y / 17)) % sprinkleColors.Length;
                        color = sprinkleColors[index];
                    }

                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GenerateEsportsNeonWallpaper()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var color = new Color(0.07f, 0.08f, 0.12f);
                    if (x % 96 < 3 || y % 96 < 3)
                    {
                        color = new Color(0.04f, 0.44f, 0.72f);
                    }

                    if ((x + y) % 180 < 4)
                    {
                        color = new Color(0.82f, 0.10f, 0.72f);
                    }

                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GenerateEsportsDarkFloor()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var tile = x % 96 < 4 || y % 96 < 4;
                    var n = Mathf.PerlinNoise(x * 0.04f, y * 0.04f);
                    var color = tile
                        ? new Color(0.10f, 0.48f, 0.62f)
                        : new Color(0.10f + n * 0.04f, 0.11f + n * 0.04f, 0.14f + n * 0.05f);
                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GenerateHotelBeddingStripe()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var stripe = y % 96 < 16;
                    var fine = Mathf.PerlinNoise(x * 0.05f, y * 0.05f) * 0.035f;
                    var color = stripe
                        ? new Color(0.66f + fine, 0.78f + fine, 0.86f + fine)
                        : new Color(0.98f - fine, 0.93f - fine, 0.84f - fine);
                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GenerateTargetPostcardArt()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var border = x < 26 || x > texture.width - 27 || y < 26 || y > texture.height - 27;
                    var sky = y > texture.height * 0.56f;
                    var sea = y > texture.height * 0.38f && !sky;
                    var n = Mathf.PerlinNoise(x * 0.018f, y * 0.018f) * 0.045f;
                    var color = sky ? new Color(0.62f + n, 0.82f + n, 0.96f) : sea ? new Color(0.18f, 0.58f + n, 0.80f + n) : new Color(0.72f + n, 0.62f + n, 0.48f);
                    if (border)
                    {
                        color = new Color(0.82f, 0.64f, 0.42f);
                    }
                    else if ((x > 92 && x < 150 && y > 150 && y < 305) || (x > 350 && x < 420 && y > 125 && y < 330))
                    {
                        color = x < 180 ? new Color(0.40f, 0.58f, 0.72f) : new Color(0.86f, 0.72f, 0.54f);
                    }

                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GenerateStarBayWindowBackdropPainted()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var u = x / (float)(texture.width - 1);
                    var v = y / (float)(texture.height - 1);
                    var paper = Mathf.PerlinNoise(x * 0.020f, y * 0.020f) * 0.026f;
                    var color = Color.Lerp(new Color(0.70f, 0.88f, 0.98f), new Color(0.98f, 0.90f, 0.76f), Mathf.Clamp01(1f - v));

                    if (v < 0.22f)
                    {
                        color = Color.Lerp(new Color(0.42f, 0.44f, 0.42f), new Color(0.66f, 0.58f, 0.48f), v / 0.22f);
                    }
                    else if (v < 0.36f)
                    {
                        var road = Mathf.Abs((u - 0.50f) * 0.44f + (v - 0.28f)) < 0.018f;
                        color = road ? new Color(0.88f, 0.78f, 0.52f) : Color.Lerp(new Color(0.48f, 0.54f, 0.54f), new Color(0.70f, 0.62f, 0.50f), (v - 0.22f) / 0.14f);
                    }
                    else if (v < 0.50f)
                    {
                        var sparkle = Mathf.PerlinNoise(120f + x * 0.075f, 90f + y * 0.050f) > 0.55f;
                        color = sparkle ? new Color(0.88f, 0.96f, 0.94f) : Color.Lerp(new Color(0.16f, 0.58f, 0.80f), new Color(0.44f, 0.76f, 0.88f), (v - 0.36f) / 0.14f);
                    }

                    var horizonGlow = Mathf.Abs(v - 0.505f) < 0.022f;
                    if (horizonGlow)
                    {
                        color = Color.Lerp(color, new Color(0.98f, 0.94f, 0.78f), 0.55f);
                    }

                    var centerDistance = Mathf.Abs(u - 0.50f);
                    if (v > 0.55f && centerDistance < 0.18f)
                    {
                        var bayFade = Mathf.Clamp01((0.18f - centerDistance) / 0.18f);
                        color = Color.Lerp(color, new Color(0.78f, 0.88f, 0.90f), bayFade * 0.20f);
                    }

                    if (u < 0.24f && v > 0.18f && v < 0.82f)
                    {
                        var balcony = Mathf.Floor(v * 18f) % 4f == 0f;
                        var vertical = Mathf.Floor(u * 34f) % 5f == 0f;
                        var window = Mathf.Abs((u * 42f) % 1f - 0.50f) < 0.11f && Mathf.Abs((v * 18f) % 1f - 0.44f) < 0.18f;
                        var facade = Color.Lerp(new Color(0.34f, 0.54f, 0.68f), new Color(0.62f, 0.74f, 0.80f), v);
                        var line = balcony || vertical ? Color.Lerp(facade, new Color(0.95f, 0.86f, 0.66f), 0.48f) : facade;
                        if (window)
                        {
                            line = Color.Lerp(line, new Color(0.78f, 0.92f, 0.98f), 0.42f);
                        }
                        color = Color.Lerp(color, line, 0.88f);
                    }
                    else if (u > 0.76f && v > 0.16f && v < 0.84f)
                    {
                        var balcony = Mathf.Floor(v * 18f) % 4f == 0f;
                        var vertical = Mathf.Floor(u * 36f) % 5f == 0f;
                        var window = Mathf.Abs((u * 40f) % 1f - 0.52f) < 0.10f && Mathf.Abs((v * 17f) % 1f - 0.50f) < 0.17f;
                        var facade = Color.Lerp(new Color(0.78f, 0.62f, 0.46f), new Color(0.96f, 0.80f, 0.60f), v);
                        var line = balcony || vertical ? Color.Lerp(facade, new Color(1.0f, 0.88f, 0.62f), 0.44f) : facade;
                        if (window)
                        {
                            line = Color.Lerp(line, new Color(0.76f, 0.90f, 0.96f), 0.36f);
                        }
                        color = Color.Lerp(color, line, 0.88f);
                    }

                    if (u > 0.28f && u < 0.42f && v > 0.24f && v < 0.70f)
                    {
