                        var facade = Color.Lerp(new Color(0.38f, 0.55f, 0.66f), new Color(0.62f, 0.72f, 0.74f), v);
                        color = balcony ? Color.Lerp(color, new Color(0.88f, 0.80f, 0.62f), 0.36f) : Color.Lerp(color, facade, 0.52f);
                    }

                    if (u > 0.59f && u < 0.72f && v > 0.24f && v < 0.68f)
                    {
                        var balcony = Mathf.Floor(v * 16f) % 4f == 0f;
                        var facade = Color.Lerp(new Color(0.78f, 0.58f, 0.42f), new Color(0.94f, 0.76f, 0.54f), v);
                        color = balcony ? Color.Lerp(color, new Color(0.96f, 0.84f, 0.62f), 0.34f) : Color.Lerp(color, facade, 0.50f);
                    }

                    var awning = (u > 0.06f && u < 0.22f && v > 0.38f && v < 0.42f) || (u > 0.78f && u < 0.95f && v > 0.40f && v < 0.44f);
                    if (awning)
                    {
                        color = Color.Lerp(color, new Color(0.22f, 0.56f, 0.70f), 0.64f);
                    }

                    var streetCenter = Mathf.Abs(u - 0.50f);
                    if (v > 0.20f && v < 0.43f && streetCenter < (0.46f - v * 0.54f))
                    {
                        var roadGlow = Mathf.Clamp01((0.43f - v) * 2.8f) * Mathf.Clamp01(1f - streetCenter * 2.1f);
                        color = Color.Lerp(color, new Color(0.78f, 0.68f, 0.52f), roadGlow * 0.34f);
                    }

                    if (v > 0.465f && v < 0.505f && u > 0.28f && u < 0.72f)
                    {
                        color = Color.Lerp(color, new Color(0.86f, 0.94f, 0.92f), 0.38f);
                    }

                    var palmTrunk = Mathf.Abs(u - 0.61f) < 0.006f && v > 0.26f && v < 0.66f;
                    var palmLeaf = Mathf.Abs(v - 0.66f) < 0.018f && Mathf.Abs(u - 0.61f) < 0.095f;
                    palmLeaf |= Mathf.Abs((u - 0.61f) + (v - 0.66f) * 1.9f) < 0.011f && Mathf.Abs(u - 0.61f) < 0.095f && v > 0.58f && v < 0.74f;
                    palmLeaf |= Mathf.Abs((u - 0.61f) - (v - 0.66f) * 1.9f) < 0.011f && Mathf.Abs(u - 0.61f) < 0.095f && v > 0.58f && v < 0.74f;
                    if (palmTrunk)
                    {
                        color = new Color(0.44f, 0.30f, 0.18f);
                    }
                    else if (palmLeaf)
                    {
                        color = new Color(0.18f, 0.54f, 0.30f);
                    }

                    var cloudOne = Mathf.Pow((u - 0.46f) / 0.13f, 2f) + Mathf.Pow((v - 0.76f) / 0.045f, 2f) < 1f;
                    var cloudTwo = Mathf.Pow((u - 0.64f) / 0.12f, 2f) + Mathf.Pow((v - 0.78f) / 0.038f, 2f) < 1f;
                    if (cloudOne || cloudTwo)
                    {
                        color = Color.Lerp(color, new Color(1f, 0.96f, 0.88f), 0.30f);
                    }

                    var distantPhotoHaze = Mathf.Clamp01((v - 0.28f) * 1.25f) * Mathf.Clamp01(1f - Mathf.Abs(u - 0.50f) * 0.82f);
                    color = Color.Lerp(color, new Color(0.82f, 0.89f, 0.88f), distantPhotoHaze * 0.16f);

                    var balconyRail = (v > 0.235f && v < 0.254f && u > 0.16f && u < 0.84f)
                        || (u > 0.22f && u < 0.23f && v > 0.13f && v < 0.34f)
                        || (u > 0.39f && u < 0.40f && v > 0.13f && v < 0.34f)
                        || (u > 0.56f && u < 0.57f && v > 0.13f && v < 0.34f)
                        || (u > 0.78f && u < 0.79f && v > 0.13f && v < 0.34f);
                    if (balconyRail)
                    {
                        color = Color.Lerp(color, new Color(0.30f, 0.31f, 0.30f), 0.72f);
                    }

                    var vignette = Mathf.Clamp01((Mathf.Abs(u - 0.50f) - 0.28f) * 1.40f);
                    color = Color.Lerp(color, new Color(0.42f, 0.48f, 0.50f), vignette * 0.08f);
                    color.r = Mathf.Clamp01(color.r + paper);
                    color.g = Mathf.Clamp01(color.g + paper);
                    color.b = Mathf.Clamp01(color.b + paper);
