                        var window = Mathf.Abs((u * 22f) % 1f - 0.50f) < 0.18f && Mathf.Abs((v * 12f) % 1f - 0.45f) < 0.18f;
                        color = Color.Lerp(color, line ? new Color(0.86f, 0.88f, 0.78f) : facade, 0.78f);
