                        var line = Mathf.Abs((v * 8f) % 1f - 0.10f) < 0.035f || Mathf.Abs((u * 10f) % 1f - 0.45f) < 0.028f;
                        var window = Mathf.Abs((u * 24f) % 1f - 0.52f) < 0.16f && Mathf.Abs((v * 12f) % 1f - 0.48f) < 0.17f;
                        color = Color.Lerp(color, line ? new Color(0.96f, 0.84f, 0.62f) : facade, 0.76f);
                        if (window)
                        {
                            color = Color.Lerp(color, new Color(0.76f, 0.90f, 0.96f), 0.40f);
                        }
                    }

                    if (u > 0.31f && u < 0.41f && v > 0.24f && v < 0.70f)
                    {
                        var t = (v - 0.24f) / 0.46f;
                        var softEdge = Mathf.Clamp01(Mathf.Min((u - 0.31f) * 26f, (0.41f - u) * 26f));
                        color = Color.Lerp(color, Color.Lerp(new Color(0.42f, 0.58f, 0.66f), new Color(0.72f, 0.76f, 0.72f), t), softEdge * 0.44f);
