                        var softEdge = Mathf.Clamp01(Mathf.Min((u - 0.60f) * 26f, (0.70f - u) * 26f));
                        color = Color.Lerp(color, Color.Lerp(new Color(0.78f, 0.58f, 0.42f), new Color(0.94f, 0.78f, 0.58f), t), softEdge * 0.42f);
                    }

