                    }

                    var palmTrunk = Mathf.Abs(u - 0.69f) < 0.006f && v > 0.23f && v < 0.62f;
                    var palmLeaf = Mathf.Abs(v - 0.63f) < 0.018f && Mathf.Abs(u - 0.69f) < 0.090f;
                    palmLeaf |= Mathf.Abs((u - 0.69f) + (v - 0.63f) * 1.8f) < 0.012f && Mathf.Abs(u - 0.69f) < 0.090f && v > 0.55f && v < 0.72f;
                    palmLeaf |= Mathf.Abs((u - 0.69f) - (v - 0.63f) * 1.8f) < 0.012f && Mathf.Abs(u - 0.69f) < 0.090f && v > 0.55f && v < 0.72f;
                    if (palmTrunk)
