                    else if (palmLeaf)
                    {
                        color = Color.Lerp(color, new Color(0.18f, 0.50f, 0.28f), 0.78f);
                    }

                    var air = Mathf.Clamp01((v - 0.36f) * 1.4f) * Mathf.Clamp01(1f - Mathf.Abs(u - 0.50f) * 0.9f);
