                {
                    var fiber = Mathf.PerlinNoise(x * 0.10f, y * 0.025f) * 0.12f;
                    var line = y % 42 < 2 ? 0.06f : 0f;
                    var color = new Color(0.58f + fiber + line, 0.39f + fiber * 0.75f + line, 0.22f + fiber * 0.45f);
                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GenerateTargetCardboardFiberWarm()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var longFiber = Mathf.PerlinNoise(x * 0.16f, y * 0.018f) * 0.10f;
                    var softMottle = Mathf.PerlinNoise(x * 0.032f + 18f, y * 0.045f) * 0.055f;
                    var crease = Mathf.Abs(x - texture.width * 0.50f) < 3f || Mathf.Abs(y - texture.height * 0.58f) < 2f ? 0.055f : 0f;
                    var edgeWear = x < 20 || y < 18 || x > texture.width - 21 || y > texture.height - 19 ? -0.045f : 0f;
                    var r = 0.64f + longFiber + softMottle - crease + edgeWear;
                    var g = 0.45f + longFiber * 0.70f + softMottle * 0.75f - crease * 0.65f + edgeWear;
                    var b = 0.26f + longFiber * 0.42f + softMottle * 0.50f - crease * 0.45f + edgeWear * 0.60f;
                    texture.SetPixel(x, y, new Color(r, g, b));
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GenerateTargetCardboardPrint()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var color = new Color(0.78f, 0.57f, 0.34f);
                    var border = x < 18 || y < 18 || x > texture.width - 19 || y > texture.height - 19;
                    var stripe = y > 230 && y < 248 && x > 90 && x < 420;
                    var icon = Mathf.Abs(x - 256) + Mathf.Abs(y - 330) < 55;
                    if (border)
                    {
                        color = new Color(0.42f, 0.25f, 0.12f);
                    }
                    else if (stripe || icon)
                    {
                        color = new Color(0.24f, 0.14f, 0.07f);
                    }

                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GenerateTargetCardboardLabelClean()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var paper = Mathf.PerlinNoise(x * 0.045f, y * 0.045f) * 0.035f;
                    var color = new Color(0.86f + paper, 0.70f + paper, 0.46f + paper * 0.55f);
                    var border = x < 20 || y < 20 || x > texture.width - 21 || y > texture.height - 21;
                    var title = x > 90 && x < 420 && y > 350 && y < 382;
                    var iconBox = x > 165 && x < 345 && y > 145 && y < 305;
                    var iconLine = iconBox && (Mathf.Abs(x - 256) < 8 || Mathf.Abs(y - 225) < 8 || Mathf.Abs(Mathf.Abs(x - 256) - Mathf.Abs(y - 225)) < 5);
                    if (border)
                    {
                        color = new Color(0.50f, 0.32f, 0.16f);
                    }
                    else if (title || iconLine)
                    {
                        color = new Color(0.26f, 0.16f, 0.08f);
                    }

                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GenerateTargetWarmPlasterWall()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var broad = Mathf.PerlinNoise(x * 0.018f, y * 0.018f) * 0.045f;
                    var fine = Mathf.PerlinNoise(120f + x * 0.13f, 80f + y * 0.13f) * 0.018f;
                    var verticalFiber = x % 96 < 2 ? 0.018f : 0f;
                    var value = 0.88f + broad + fine - verticalFiber;
                    var color = new Color(value + 0.035f, value + 0.020f, value);
                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GenerateTargetCleanWallPatch()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var u = x / (float)(texture.width - 1);
                    var v = y / (float)(texture.height - 1);
                    var broad = Mathf.PerlinNoise(x * 0.008f, y * 0.008f) * 0.025f;
                    var fine = Mathf.PerlinNoise(300f + x * 0.095f, 180f + y * 0.095f) * 0.010f;
                    var plasterFiber = Mathf.PerlinNoise(70f + x * 0.018f, y * 0.180f) * 0.014f;
                    var handTrowel = Mathf.PerlinNoise(520f + x * 0.035f, 210f + y * 0.011f) * 0.012f;
                    var value = 0.890f + broad + fine + plasterFiber + handTrowel;
                    var softVertical = x % 224 < 2 ? 0.004f : 0f;
                    var softHorizontal = y % 210 < 2 ? 0.003f : 0f;
                    var warmFalloff = Mathf.Clamp01(1f - v) * 0.014f + Mathf.Clamp01(1f - Mathf.Abs(u - 0.55f) * 1.35f) * 0.008f;
                    var color = new Color(
                        value + 0.044f + warmFalloff - softVertical,
                        value + 0.030f + warmFalloff * 0.60f - softVertical - softHorizontal,
                        value + 0.010f - softVertical - softHorizontal);
                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GenerateTargetSoftGridTile()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var tileX = x % 160;
                    var tileY = y % 160;
                    var tileIndexX = x / 160;
                    var tileIndexY = y / 160;
                    var edgeDistance = Mathf.Min(Mathf.Min(tileX, tileY), Mathf.Min(159 - tileX, 159 - tileY));
                    var groutBlend = Mathf.Clamp01((2.2f - edgeDistance) / 2.2f) * 0.46f;
                    var tileVariation = (Mathf.PerlinNoise(tileIndexX * 0.77f + 12f, tileIndexY * 0.77f + 4f) - 0.5f) * 0.014f;
                    var n = Mathf.PerlinNoise(x * 0.012f, y * 0.012f) * 0.014f;
                    var fineStone = Mathf.PerlinNoise(220f + x * 0.082f, 180f + y * 0.082f) * 0.004f;
                    var diagonalRub = Mathf.PerlinNoise(80f + (x + y) * 0.030f, 40f + y * 0.010f) * 0.004f;
                    var baseValue = 0.835f + tileVariation + n + fineStone + diagonalRub;
                    var tileColor = new Color(baseValue + 0.014f, baseValue + 0.010f, baseValue - 0.002f);
                    var groutColor = new Color(0.790f, 0.785f, 0.755f);
                    var color = Color.Lerp(tileColor, groutColor, groutBlend);
                    if (tileX > 22 && tileX < 42 && tileY > 112 && tileY < 119)
                    {
                        color = Color.Lerp(color, new Color(0.80f, 0.79f, 0.75f), 0.035f);
                    }
                    if (tileX > 104 && tileX < 134 && tileY > 30 && tileY < 34)
                    {
                        color = Color.Lerp(color, new Color(0.90f, 0.87f, 0.78f), 0.045f);
                    }

                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GenerateTargetPremiumPinkBeddingSoft()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var u = x / (float)(texture.width - 1);
                    var v = y / (float)(texture.height - 1);
                    var cloth = Mathf.PerlinNoise(x * 0.026f, y * 0.034f) * 0.030f;
                    var microWeave = Mathf.Sin(x * 0.50f) * 0.004f + Mathf.Sin(y * 0.44f) * 0.004f;
                    var fold = Mathf.Sin((x + y * 0.35f) * 0.026f) * 0.012f;
                    var softCenter = Mathf.Clamp01(1f - Mathf.Abs(u - 0.50f) * 1.9f) * Mathf.Clamp01(1f - Mathf.Abs(v - 0.52f) * 2.0f) * 0.035f;
                    var stitch = Mathf.Abs((x % 146) - 73) < 2 || Mathf.Abs((y % 132) - 66) < 2;
                    var color = new Color(1.0f, 0.61f + cloth + fold + microWeave + softCenter, 0.755f + cloth * 0.8f + fold * 0.55f + microWeave + softCenter * 0.65f);
                    if (stitch)
                    {
                        color = Color.Lerp(color, new Color(1.0f, 0.81f, 0.875f), 0.18f);
                    }

                    var cellX = x % 146 - 73;
                    var cellY = y % 132 - 66;
                    var softDot = cellX * cellX + cellY * cellY < 6 * 6;
                    if (softDot)
                    {
                        color = Color.Lerp(color, new Color(1.0f, 0.86f, 0.90f), 0.12f);
                    }

                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GenerateTargetPremiumPinkBedding()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var n = Mathf.PerlinNoise(x * 0.035f, y * 0.035f) * 0.035f;
                    var quiltX = x % 128 < 4;
                    var quiltY = y % 128 < 4;
                    var color = quiltX || quiltY
                        ? new Color(1f, 0.79f, 0.87f)
                        : new Color(1f, 0.61f + n, 0.75f + n);
                    var cellX = x % 128 - 64;
                    var cellY = y % 128 - 64;
                    var dot = cellX * cellX + cellY * cellY < 7 * 7;
                    var heart = Mathf.Pow(cellX / 18f, 2f) + Mathf.Pow((cellY + 5f) / 14f, 2f) < 1f && !(Mathf.Abs(cellX) < 5 && cellY > -12 && cellY < 1);
                    if (dot)
                    {
                        color = new Color(1f, 0.86f, 0.91f);
                    }
                    else if (heart)
                    {
                        color = new Color(1f, 0.48f, 0.66f);
                    }

                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GenerateTargetPinkCurtainFabric()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var pleat = Mathf.Sin(x * 0.075f) * 0.09f;
                    var noise = Mathf.PerlinNoise(x * 0.040f, y * 0.025f) * 0.035f;
                    var stripe = x % 72 < 5;
                    var color = new Color(1f, 0.68f + pleat + noise, 0.80f + pleat * 0.45f + noise);
                    if (stripe)
                    {
                        color = Color.Lerp(color, new Color(0.78f, 0.34f, 0.48f), 0.35f);
                    }

                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D GenerateTargetPinkCurtainFabricSoft()
        {
            var texture = NewGeneratedTexture();
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    var verticalFold = Mathf.Sin(x * 0.052f) * 0.040f + Mathf.Sin(x * 0.115f + 1.2f) * 0.018f;
                    var woven = Mathf.PerlinNoise(x * 0.035f, y * 0.075f) * 0.030f;
                    var lowerShade = Mathf.Clamp01((texture.height - y) / (float)texture.height) * 0.025f;
                    var color = new Color(1f, 0.58f + woven + verticalFold * 0.45f - lowerShade, 0.72f + woven * 0.8f + verticalFold * 0.35f - lowerShade);
                    texture.SetPixel(x, y, color);
                }
            }

            texture.Apply();
            return texture;
        }

        private static Texture2D NewGeneratedTexture()
        {
            var texture = new Texture2D(512, 512, TextureFormat.RGB24, false);
            texture.wrapMode = TextureWrapMode.Repeat;
            texture.filterMode = FilterMode.Bilinear;
            return texture;
        }

        private static void SaveGeneratedTexture(string fileName, Texture2D texture)
        {
            var path = GeneratedTextureFolder + "/" + fileName;
            File.WriteAllBytes(path, texture.EncodeToPNG());
            Object.DestroyImmediate(texture);
            AssetDatabase.ImportAsset(path);
            var importer = AssetImporter.GetAtPath(path) as TextureImporter;
            if (importer != null)
            {
                importer.wrapMode = TextureWrapMode.Repeat;
                importer.filterMode = FilterMode.Bilinear;
                importer.textureCompression = TextureImporterCompression.Compressed;
                importer.SaveAndReimport();
            }
        }

