                    }
                    KenneyModelFit(parent, "可爱梳妆台_CC0镜台", "bathroomMirror", new Vector3(0.95f, 0.08f, -0.2f), Quaternion.identity, new Vector3(0.64f, 1.0f, 0.28f));
                    Cube(parent, "可爱粉色床罩样板", new Vector3(-0.55f, 0.46f, 0.06f), new Vector3(1.0f, 0.05f, 1.0f), "PinkWallpaper");
