                    KenneyModelFit(parent, "木质自然餐桌_CC0模型", "table", new Vector3(0.78f, 0.08f, -0.08f), Quaternion.identity, new Vector3(1.05f, 0.78f, 0.86f));
                    break;
                case "现代简约":
