                case "蛋糕主题":
                    GeneratedBlenderModelFit(parent, "蛋糕奶油床_Blender生成", "蛋糕奶油床", new Vector3(-0.55f, 0.08f, 0.06f), Quaternion.identity, new Vector3(1.20f, 0.82f, 1.45f));
                    KenneyModelFit(parent, "蛋糕圆地毯_CC0模型", "rugRound", new Vector3(-0.55f, 0.09f, 0.12f), Quaternion.identity, new Vector3(1.15f, 0.08f, 1.15f));
                    Furniture(parent, FurnitureDisplayName(secondFurnitureId), secondFurnitureId, new Vector3(0.86f, 0.08f, -0.15f), Quaternion.identity);
                    break;
                case "电竞主题":
                    if (GeneratedBlenderModelFit(parent, "电竞霓虹电脑桌_Blender生成", "电竞霓虹电脑桌", new Vector3(-0.45f, 0.08f, 0.08f), Quaternion.identity, new Vector3(1.25f, 1.02f, 0.72f)) == null)
