        private static GameObject KenneyModelFit(Transform parent, string name, string modelName, Vector3 localPosition, Quaternion localRotation, Vector3 targetSize)
        {
            var path = "Assets/BubuTown/External/CC0/Kenney/FurnitureKit/Raw/Models/" + modelName + ".fbx";
            var asset = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (asset == null)
            {
                return null;
            }

            var instance = PrefabUtility.InstantiatePrefab(asset) as GameObject;
            if (instance == null)
            {
                return null;
            }

            instance.name = name;
            instance.transform.SetParent(parent, false);
            instance.transform.localPosition = localPosition;
            instance.transform.localRotation = localRotation;
            instance.transform.localScale = Vector3.one;
            FitToBounds(instance, targetSize);
            DropToLocalGround(parent, instance, localPosition.y);
            return instance;
        }

        private static void ApplyGeneratedBlenderFurnitureMaterials(GameObject instance)
        {
            var renderers = instance.GetComponentsInChildren<Renderer>();
            foreach (var renderer in renderers)
            {
                var key = (renderer.transform.name + "_" + renderer.name + "_" + (renderer.sharedMaterial != null ? renderer.sharedMaterial.name : "")).ToLowerInvariant();
                renderer.sharedMaterial = GeneratedBlenderFurnitureMaterial(key);
            }
        }

        private static Material GeneratedBlenderFurnitureMaterial(string key)
        {
            if (key.Contains("镜面") || key.Contains("显示器") || key.Contains("屏"))
            {
                return Mat("Glass");
            }

            if (key.Contains("海景画芯") || key.Contains("海湾") || key.Contains("蓝天画芯"))
            {
                return Mat("TargetPostcardArt");
            }

            if (key.Contains("软木便签板"))
