        private static GameObject PolyHavenModelFit(Transform parent, string name, string assetName, Vector3 localPosition, Quaternion localRotation, Vector3 targetSize)
        {
            var path = PolyHavenModelFolder + "/" + assetName + "/" + assetName + "_1k.fbx";
            var asset = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (asset == null)
            {
                return null;
            }

            var instance = PrefabUtility.InstantiatePrefab(asset) as GameObject;
            if (instance == null)
            {
                return null;
            }

            instance.name = name;
            instance.transform.SetParent(parent, false);
            instance.transform.localPosition = localPosition;
            instance.transform.localRotation = localRotation;
            instance.transform.localScale = Vector3.one;
            ApplyPolyHavenMaterial(instance, assetName);
            FitToBounds(instance, targetSize);
            DropToLocalGround(parent, instance, localPosition.y);
            return instance;
        }

