        private static void RecolorInstance(GameObject instance, string materialName)
        {
            var material = Mat(materialName);
            if (material == null)
            {
                return;
            }

            var renderers = instance.GetComponentsInChildren<Renderer>();
            foreach (var renderer in renderers)
            {
                renderer.sharedMaterial = material;
            }
        }

        private static void RecolorLatestChildren(Transform parent, string objectName, string materialName)
        {
            var target = parent.Find(objectName);
            if (target != null)
            {
                RecolorInstance(target.gameObject, materialName);
            }
        }

        private static void ConfigurePolyHavenNormalMaps()
        {
            ConfigureNormalMap(PolyHavenModelFolder + "/Sofa_01/Sofa_01_nor_gl_1k.jpg");
            ConfigureNormalMap(PolyHavenModelFolder + "/CoffeeTable_01/CoffeeTable_01_nor_gl_1k.jpg");
