            ConfigureNormalMap(PolyHavenModelFolder + "/ClassicNightstand_01/ClassicNightstand_01_nor_gl_1k.jpg");
            ConfigureNormalMap(PolyHavenModelFolder + "/potted_plant_01/potted_plant_01_leaves_nor_gl_1k.jpg");
            ConfigureNormalMap(PolyHavenModelFolder + "/potted_plant_01/potted_plant_01_pot_nor_gl_1k.jpg");
        }

        private static void ApplyPolyHavenMaterial(GameObject instance, string assetName)
        {
            var renderers = instance.GetComponentsInChildren<Renderer>();
            foreach (var renderer in renderers)
            {
                var sourceName = renderer.name + "_" + (renderer.sharedMaterial != null ? renderer.sharedMaterial.name : "");
                renderer.sharedMaterial = PolyHavenMaterial(assetName, sourceName);
            }
        }

        private static Material PolyHavenMaterial(string assetName, string sourceMaterialName)
        {
            var suffix = "";
            if (assetName == "potted_plant_01")
            {
                suffix = sourceMaterialName.ToLowerInvariant().Contains("pot") ? "_pot" : "_leaves";
            }

            var materialPath = PolyHavenMaterialFolder + "/" + assetName + suffix + ".mat";
            var material = AssetDatabase.LoadAssetAtPath<Material>(materialPath);
            if (material == null)
            {
                material = new Material(Shader.Find("Universal Render Pipeline/Lit"));
                AssetDatabase.CreateAsset(material, materialPath);
            }

            var baseName = assetName + suffix;
            var albedoPath = PolyHavenModelFolder + "/" + assetName + "/" + baseName + "_diff_1k.jpg";
            var normalPath = PolyHavenModelFolder + "/" + assetName + "/" + baseName + "_nor_gl_1k.jpg";
            var albedo = AssetDatabase.LoadAssetAtPath<Texture2D>(albedoPath);
            var normal = AssetDatabase.LoadAssetAtPath<Texture2D>(normalPath);
            if (albedo != null)
            {
                material.SetTexture("_BaseMap", albedo);
                material.SetColor("_BaseColor", Color.white);
            }
            else
            {
                material.SetColor("_BaseColor", PolyHavenFallbackColor(assetName, suffix));
            }

            if (normal != null)
            {
                material.EnableKeyword("_NORMALMAP");
                material.SetTexture("_BumpMap", normal);
                material.SetFloat("_BumpScale", 0.55f);
            }

            material.SetFloat("_Smoothness", assetName == "Sofa_01" ? 0.38f : 0.24f);
            EditorUtility.SetDirty(material);
            return material;
        }

        private static Color PolyHavenFallbackColor(string assetName, string suffix)
        {
            if (assetName == "Sofa_01")
            {
                return new Color(0.74f, 0.68f, 0.62f);
            }

            if (assetName == "potted_plant_01" && suffix == "_leaves")
            {
                return new Color(0.22f, 0.56f, 0.26f);
            }

            if (assetName == "potted_plant_01" && suffix == "_pot")
            {
                return new Color(0.54f, 0.32f, 0.18f);
            }

            return new Color(0.58f, 0.42f, 0.25f);
        }

        private static void FitToBounds(GameObject instance, Vector3 targetSize)
        {
            var bounds = CombinedBounds(instance);
            if (bounds.size == Vector3.zero)
            {
                return;
            }

            var scale = float.MaxValue;
            if (targetSize.x > 0.001f && bounds.size.x > 0.001f)
            {
                scale = Mathf.Min(scale, targetSize.x / bounds.size.x);
            }

            if (targetSize.y > 0.001f && bounds.size.y > 0.001f)
            {
                scale = Mathf.Min(scale, targetSize.y / bounds.size.y);
            }

            if (targetSize.z > 0.001f && bounds.size.z > 0.001f)
            {
                scale = Mathf.Min(scale, targetSize.z / bounds.size.z);
            }

            if (scale < float.MaxValue)
            {
                instance.transform.localScale *= scale;
            }
        }

        private static void DropToLocalGround(Transform parent, GameObject instance, float localGroundY)
        {
            var bounds = CombinedBounds(instance);
            if (bounds.size == Vector3.zero)
            {
                return;
            }

            var desiredWorldY = parent.TransformPoint(new Vector3(0f, localGroundY, 0f)).y;
            var delta = desiredWorldY - bounds.min.y;
            instance.transform.position += Vector3.up * delta;
        }

        private static Bounds CombinedBounds(GameObject instance)
        {
            var renderers = instance.GetComponentsInChildren<Renderer>();
            if (renderers.Length == 0)
            {
                return new Bounds(instance.transform.position, Vector3.zero);
            }

            var bounds = renderers[0].bounds;
            for (var i = 1; i < renderers.Length; i++)
            {
                bounds.Encapsulate(renderers[i].bounds);
            }

            return bounds;
        }

        private static void Plant(Transform parent, string name, Vector3 localPosition, float scale)
        {
            var group = Group(parent, name);
            group.localPosition = localPosition;
            Sphere(group, "圆润花盆", new Vector3(0f, 0.15f * scale, 0f), new Vector3(0.28f * scale, 0.17f * scale, 0.28f * scale), "PlantPot");
            Sphere(group, "盆土", new Vector3(0f, 0.29f * scale, 0f), new Vector3(0.22f * scale, 0.030f * scale, 0.22f * scale), "PlantSoil");
            Sphere(group, "低矮叶冠", new Vector3(0f, 0.55f * scale, 0f), new Vector3(0.50f * scale, 0.28f * scale, 0.46f * scale), "PlantLeaf");
            var left = Sphere(group, "椭圆叶片左", new Vector3(-0.20f * scale, 0.72f * scale, 0.04f * scale), new Vector3(0.14f * scale, 0.040f * scale, 0.30f * scale), "PlantLeaf");
            left.transform.localRotation = Quaternion.Euler(0f, 28f, -18f);
            var right = Sphere(group, "椭圆叶片右", new Vector3(0.22f * scale, 0.68f * scale, -0.04f * scale), new Vector3(0.14f * scale, 0.040f * scale, 0.28f * scale), "PlantLeaf");
            right.transform.localRotation = Quaternion.Euler(0f, -24f, 16f);
            Cube(group, "细叶柄左", new Vector3(-0.06f * scale, 0.45f * scale, 0.02f * scale), new Vector3(0.018f * scale, 0.24f * scale, 0.014f * scale), "PlantStem");
            Cube(group, "细叶柄右", new Vector3(0.08f * scale, 0.44f * scale, -0.02f * scale), new Vector3(0.018f * scale, 0.22f * scale, 0.014f * scale), "PlantStem");
        }

