        private static void Label(Transform parent, string name, string text, Vector3 localPosition, float size)
        {
            var label = new GameObject(name);
            label.transform.SetParent(parent, false);
            label.transform.localPosition = localPosition;
            label.transform.localRotation = Quaternion.Euler(65f, 0f, 0f);
            var mesh = label.AddComponent<TextMesh>();
            mesh.text = text;
            mesh.fontSize = 28;
            mesh.characterSize = size;
            mesh.anchor = TextAnchor.MiddleCenter;
            mesh.alignment = TextAlignment.Center;
            mesh.color = new Color(0.08f, 0.10f, 0.12f);
        }

        private static Material Mat(string name)
        {
            return AssetDatabase.LoadAssetAtPath<Material>(MaterialFolder + "/" + name + ".mat");
        }

        private static void MakeMat(string name, Color color)
        {
            var path = MaterialFolder + "/" + name + ".mat";
            var material = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (material == null)
            {
                material = new Material(PreferredShader());
                AssetDatabase.CreateAsset(material, path);
            }

            material.shader = PreferredShader();
            material.color = color;
            SetMaterialColor(material, color);
            EditorUtility.SetDirty(material);
        }

        private static void MakeTransparentMat(string name, Color color)
        {
            var path = MaterialFolder + "/" + name + ".mat";
            var material = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (material == null)
            {
                material = new Material(PreferredShader());
                AssetDatabase.CreateAsset(material, path);
            }

            material.shader = PreferredShader();
            SetMaterialColor(material, color);
            if (material.HasProperty("_Surface"))
            {
                material.SetFloat("_Surface", 1f);
                material.SetFloat("_Blend", 0f);
                material.SetFloat("_SrcBlend", (float)UnityEngine.Rendering.BlendMode.SrcAlpha);
                material.SetFloat("_DstBlend", (float)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
                material.SetFloat("_ZWrite", 0f);
                material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
                material.DisableKeyword("_ALPHATEST_ON");
                material.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent;
            }
            else
            {
                material.SetFloat("_Mode", 3f);
                material.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.SrcAlpha);
                material.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
                material.SetInt("_ZWrite", 0);
                material.DisableKeyword("_ALPHATEST_ON");
                material.EnableKeyword("_ALPHABLEND_ON");
                material.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent;
            }

            EditorUtility.SetDirty(material);
        }

        private static void MakeTexturedMat(string name, Color tint, string albedoPath, string normalPath, Vector2 tiling)
        {
            var path = MaterialFolder + "/" + name + ".mat";
            var material = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (material == null)
            {
                material = new Material(PreferredShader());
                AssetDatabase.CreateAsset(material, path);
            }

            material.shader = PreferredShader();
            SetMaterialColor(material, tint);

            var albedo = AssetDatabase.LoadAssetAtPath<Texture2D>(albedoPath);
            if (albedo != null)
            {
                SetMaterialTexture(material, "_BaseMap", "_MainTex", albedo);
                material.mainTextureScale = tiling;
                if (material.HasProperty("_BaseMap"))
                {
                    material.SetTextureScale("_BaseMap", tiling);
                }
            }

            if (!string.IsNullOrEmpty(normalPath))
            {
                var normal = AssetDatabase.LoadAssetAtPath<Texture2D>(normalPath);
                if (normal != null)
                {
                    SetMaterialTexture(material, "_BumpMap", "_BumpMap", normal);
                    if (material.HasProperty("_BumpScale"))
                    {
                        material.SetFloat("_BumpScale", 0.45f);
                    }

                    material.EnableKeyword("_NORMALMAP");
                }
            }

            if (material.HasProperty("_Smoothness"))
            {
                material.SetFloat("_Smoothness", 0.18f);
            }

            EditorUtility.SetDirty(material);
        }

        private static void SetMaterialColor(Material material, Color color)
        {
            material.color = color;
            if (material.HasProperty("_BaseColor"))
            {
                material.SetColor("_BaseColor", color);
            }
        }

        private static void SetMaterialTexture(Material material, string preferredProperty, string fallbackProperty, Texture texture)
        {
            if (material.HasProperty(preferredProperty))
            {
                material.SetTexture(preferredProperty, texture);
            }
            else if (material.HasProperty(fallbackProperty))
            {
                material.SetTexture(fallbackProperty, texture);
            }
        }

        private static void ConfigureNormalMap(string path)
        {
            var importer = AssetImporter.GetAtPath(path) as TextureImporter;
            if (importer == null)
            {
                return;
            }

            if (importer.textureType != TextureImporterType.NormalMap)
            {
                importer.textureType = TextureImporterType.NormalMap;
                importer.SaveAndReimport();
            }
        }

        private static Shader PreferredShader()
        {
            var shader = Shader.Find("Universal Render Pipeline/Lit");
            if (shader == null)
            {
                shader = Shader.Find("Standard");
            }

            return shader;
        }

        private static void Require(string path)
        {
            if (GameObject.Find(path) == null)
            {
                throw new System.Exception("[StarBay] Missing required interior object: " + path);
            }
        }

        private static void RequireRuntimeResource(string path)
        {
            if (Resources.Load<GameObject>(path) == null)
            {
                throw new System.Exception("[StarBay] Missing runtime furniture resource: " + path);
            }
        }

        private sealed class SuiteRefs
        {
            public Renderer[] Walls;
            public Renderer Floor;
            public Light[] Lights;
            public Transform PlacementRoot;
            public Transform PreviewRoot;
        }

        private readonly struct CatalogStyle
        {
            public readonly string Name;
            public readonly Color Furniture;
            public readonly Color Wallpaper;
            public readonly Color Floor;
            public readonly Color Light;

            public CatalogStyle(string name, Color furniture, Color wallpaper, Color light)
            {
                Name = name;
                Furniture = furniture;
                Wallpaper = wallpaper;
                Floor = Color.Lerp(furniture, wallpaper, 0.35f);
                Light = light;
            }
        }

        private readonly struct CatalogPreviewStyle
        {
            public readonly Color Furniture;
            public readonly Color Wallpaper;
            public readonly Color Floor;
            public readonly Color Light;

            public CatalogPreviewStyle(Color furniture, Color wallpaper, Color floor, Color light)
            {
                Furniture = furniture;
                Wallpaper = wallpaper;
                Floor = floor;
                Light = light;
            }
        }

        private readonly struct FurniturePrefabSpec
        {
            public readonly string ChineseName;
            public readonly string ModelName;
            public readonly Vector3 TargetSize;
            public readonly Quaternion Rotation;

            public FurniturePrefabSpec(string chineseName, string modelName, Vector3 targetSize, Quaternion rotation)
            {
                ChineseName = chineseName;
                ModelName = modelName;
                TargetSize = targetSize;
                Rotation = rotation;
            }
        }
    }
}
